@startuml

class User {
  + UserID : string
  + Name : string
  + Address : string
  + Birthday : date
}

class BusinessOwner extends User {
  + LinkedInAccount : string
}

class PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : double
}

class HungryCustomer extends User {
  + DeliveryAddress : string
}

class Order {
  + OrderID : string
  + DateTime : datetime
  + LatestDeliveryTime : time
  + NumberOfPeople : int
}

class EntertainmentOrder extends Order {
  + EntertainmentType : string
  + Duration : int
}

class Entertainer extends User {
  + StageName : string
  + Bio : string
  + PricePer30Minutes : double
}

class Availability {
  + Day : string
}

BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
HungryCustomer "1" -- "*" Order : makes
Order "*" -- "1..*" Pizza : contains
EntertainmentOrder "*" -- "1" Entertainer : fulfilled by
Entertainer "*" -- "*" PizzaRestaurant : works with
Entertainer "1" -- "*" Availability : has
PizzaRestaurant "1" -- "*" Availability : has

@enduml

